package net.officefloor.hq.app.role;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ReadListener;
import jakarta.servlet.ServletException;
import jakarta.servlet.ServletInputStream;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletRequestWrapper;
import jakarta.servlet.http.HttpServletResponse;
import java.io.BufferedReader;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import tools.jackson.databind.json.JsonMapper;

/** Refuse every change a viewer asks for on a sheet, and every change to an archived sheet, before any endpoint
 *  reads or writes anything: each POST or PUT under a sheet (all but loading the sheet itself) whose signed-in user
 *  (the body's {@code user}) is a viewer on that sheet, or on a sheet that is archived, is answered 403 with the
 *  reason, and nothing is written or audited. A bulk open is left to its endpoint, which counts every selected claim
 *  refused for a viewer or on an archived sheet, and so is a bulk reassign or bulk re-date; so is a viewer's bulk grade or bulk retire, which changes nobody, and a viewer's generating of the plans' claims, which makes none; so is a bulk settle by a viewer or on an archived sheet, which counts every selected claim refused. Every change sent from a
 *  screen showing the sheet as of a date (the X-As-Of header), a bulk one included, is answered 403 the same way. */
@Component
public class RefuseViewerChanges extends OncePerRequestFilter {

    /** A change under a sheet: /api/sheets/{sheetId}/... (loading the sheet, /api/sheets/{sheetId}, is not one). */
    private static final Pattern CHANGE = Pattern.compile("^/api/sheets/([^/]+)/.+$");

    /** A bulk open, left to the endpoint: it refuses each selected claim a viewer's role may not open (none), and
     *  answers how many it opened and refused, writing nothing. */
    private static final Pattern BULK_OPEN = Pattern.compile("^/api/sheets/[^/]+/bulk-(open|reassign|redate)$");

    /** A bulk grade or retire, or generating the plans' claims, left to the endpoint for a viewer: it changes nothing
     *  and answers that none was changed (none generated). */
    private static final Pattern BULK_GRADE = Pattern.compile("^/api/sheets/[^/]+/(bulk-(grade|retire)|plans/generate)$");

    /** A bulk settle, left to the endpoint for a viewer or on an archived sheet: it counts every selected claim refused. */
    private static final Pattern BULK_SETTLE = Pattern.compile("^/api/sheets/[^/]+/bulk-settle$");

    /** The header a screen showing the sheet as of a date sends every change with: the change is refused. */
    public static final String AS_OF = "X-As-Of";

    private final RoleRepository roles;
    private final SheetRepository sheets;
    private final JsonMapper json = JsonMapper.builder().build();

    public RefuseViewerChanges(RoleRepository roles, SheetRepository sheets) {
        this.roles = roles;
        this.sheets = sheets;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String method = request.getMethod();
        String path = request.getRequestURI().substring(request.getContextPath().length());
        Matcher change = CHANGE.matcher(path);
        if (method.equals("GET") || method.equals("HEAD") || method.equals("OPTIONS") || !change.matches()) {
            chain.doFilter(request, response);
            return;
        }
        String asOf = request.getHeader(AS_OF);
        if (asOf != null && !asOf.isBlank()) {
            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
            response.setContentType("text/plain;charset=UTF-8");
            response.getWriter().write("The sheet is shown as of " + asOf.trim() + ": clear the as-of date to change it.");
            return;
        }
        if (BULK_OPEN.matcher(path).matches()) {
            chain.doFilter(request, response);
            return;
        }
        byte[] body = request.getInputStream().readAllBytes();
        String sheetId = URLDecoder.decode(change.group(1), StandardCharsets.UTF_8).trim();
        String user = user(body);
        if (user != null && !BULK_GRADE.matcher(path).matches() && !BULK_SETTLE.matcher(path).matches()
                && Role.VIEWER.equals(roles.of(sheetId, user))) {
            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
            response.setContentType("text/plain;charset=UTF-8");
            response.getWriter().write("A viewer can change nothing on this sheet.");
            return;
        }
        if (!BULK_SETTLE.matcher(path).matches() && sheets.archived(sheetId)) {
            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
            response.setContentType("text/plain;charset=UTF-8");
            response.getWriter().write("This sheet is archived: nothing on it can be changed.");
            return;
        }
        chain.doFilter(new Rereadable(request, body), response);
    }

    /** The signed-in user the body names (trimmed), or null when there is none. */
    private String user(byte[] body) {
        try {
            Object user = json.readValue(body, Map.class).get("user");
            return user instanceof String name && !name.isBlank() ? name.trim() : null;
        } catch (RuntimeException e) {
            return null; // not a JSON object: left to the endpoint to refuse
        }
    }

    /** The request with its body, already read here, readable again by the endpoint. */
    private static final class Rereadable extends HttpServletRequestWrapper {
        private final byte[] body;

        Rereadable(HttpServletRequest request, byte[] body) {
            super(request);
            this.body = body;
        }

        @Override
        public ServletInputStream getInputStream() {
            ByteArrayInputStream in = new ByteArrayInputStream(body);
            return new ServletInputStream() {
                @Override
                public int read() {
                    return in.read();
                }

                @Override
                public int read(byte[] b, int off, int len) {
                    return in.read(b, off, len);
                }

                @Override
                public boolean isFinished() {
                    return in.available() == 0;
                }

                @Override
                public boolean isReady() {
                    return true;
                }

                @Override
                public void setReadListener(ReadListener listener) {
                    throw new UnsupportedOperationException();
                }
            };
        }

        @Override
        public BufferedReader getReader() {
            return new BufferedReader(new InputStreamReader(getInputStream(), StandardCharsets.UTF_8));
        }

        @Override
        public int getContentLength() {
            return body.length;
        }

        @Override
        public long getContentLengthLong() {
            return body.length;
        }
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A person's plan: a DRAFT claim of the amount for every plan date (the start, then every N days) up to the end,
 *  made when the plans are generated; `generated` is how many claims it has made so far. A monthly plan has no `every`
 *  but a `day` of the month (1 to 31), falling on the month's last day in a shorter month. */
export type Plan = {
  id: number;
  personId: number;
  amount: string;
  start: string;
  every: number | null;
  day: number | null;
  end: string;
  generated: number;
  /** The first five plan dates after the sheet's today and on or before the end, in order. */
  nextDates: string[];
};

export const plansKey = (sheetId: string) => ['sheet', sheetId, 'plans'] as const;

/** Every plan on the sheet, in the order they were added. */
export function usePlans(sheetId: string) {
  return useQuery({
    queryKey: plansKey(sheetId),
    queryFn: () => getJson<Plan[]>(`/api/sheets/${encodeURIComponent(sheetId)}/plans`),
  });
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonRow } from '../../slots/defs/personRow';
import { usePersonError } from '../people/rowError';
import type { Person } from '../people/people';
import { plansKey, usePlans } from './plans';
import type { Plan } from './plans';

/** The person's plans, each with how many claims it has made so far and its next five dates after the sheet's today, and the form that adds one: an amount, a start
 *  date, every N days (a whole number, at least 1) or
 *  monthly on a day of the month (1 to 31), and an end date, not before the start. */
function PersonPlans({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const plans = (usePlans(sheetId).data ?? []).filter((p) => p.personId === person.id);
  const [amount, setAmount] = useState('');
  const [start, setStart] = useState('');
  const [every, setEvery] = useState('');
  const [day, setDay] = useState('');
  const [end, setEnd] = useState('');
  const { error, setError, begin } = usePersonError(sheetId, person.id);
  const once = useSubmitOnce();

  const add = useMutation({
    mutationFn: (body: { user: string; amount: string; start: string; every: string; day: string; end: string }) =>
      postJson<Plan>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/plans`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: plansKey(sheetId) });
      setAmount('');
      setStart('');
      setEvery('');
      setDay('');
      setEnd('');
    },
    onError: (e) =>
      setError(e instanceof HttpError && e.body ? e.body : `Could not add a plan for ${person.name}.`),
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    begin();
    if (!once.start()) return;
    add.mutate({ user, amount: amount.trim(), start: start.trim(), every: every.trim(), day: day.trim(), end: end.trim() });
  };

  const change = (set: (v: string) => void) => (e: { target: { value: string } }) => {
    set(e.target.value);
    setError('');
  };

  return (
    <td>
      Plans
      <ul>
        {plans.map((p) => (
          <li key={p.id} data-testid={`plan-row-${p.id}`}>
            {p.amount} from {p.start} {p.day !== null ? `monthly on day ${p.day}` : `every ${p.every} days`} to {p.end}; made{' '}
            <span data-testid="plan-generated">{p.generated}</span>; next{' '}
            <span data-testid="plan-next-dates">{p.nextDates.join(', ')}</span>
          </li>
        ))}
      </ul>
      <form onSubmit={submit} style={{ display: 'inline' }}>
        <input data-testid="plan-form-amount" placeholder="amount" value={amount} onChange={change(setAmount)} />{' '}
        <input data-testid="plan-form-start" placeholder="start yyyy-mm-dd" value={start} onChange={change(setStart)} />{' '}
        <input data-testid="plan-form-every" placeholder="every N days" value={every} onChange={change(setEvery)} />{' '}
        <input data-testid="plan-form-day" placeholder="or day of month" value={day} onChange={change(setDay)} />{' '}
        <input data-testid="plan-form-end" placeholder="end yyyy-mm-dd" value={end} onChange={change(setEnd)} />{' '}
        <button type="submit" data-testid="plan-form-submit" disabled={add.isPending}>
          Add plan
        </button>
      </form>
      {error && (
        <p data-testid="plan-error" role="alert">
          {error}
        </p>
      )}
    </td>
  );
}

export const contribution = PersonRow.fill({ order: 47, Component: PersonPlans });
-- Whether the claim is held: only an OPEN or PENDING claim is held or released. A held OPEN claim not bound by a
-- statement is left out of every live total, as a held person's claims are.
ALTER TABLE claim ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim_history ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
