package net.officefloor.hq.app.plan;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** ${kind} the loaded plan from the sheet's today. Refused when the plan is ${other}, or the sheet has no today. */
public class SavePlan$kind {
    public void save(@Val PlanPauseRequest input, @Val Plan loaded, SheetRepository sheets, PlanRepository repository,
            Out<Plan> saved) throws InvalidPlanException {
        LocalDate today = sheets.today(loaded.sheetId());
        if (today == null) {
            throw new InvalidPlanException("Set the sheet's today before ${verb == pause ? "" : ""}${verb === undefined ? "" : ""}${verb}ing a plan.");
        }
        if (!repository.${verb}(loaded.id(), today, input.user())) {
            throw new InvalidPlanException("The plan is ${other}.");
        }
        saved.set(repository.find(loaded.sheetId(), loaded.id()));
    }
}
